materials={s.id:s.to_dict() for s in db.collection("materials").stream()}
for model in payload:
 for item in model["data"]["items"]:
  if item["matId"]:
   current=materials.get(item["matId"])
   assert current and current.get("active") is not False and current.get("status")!="inactive", "Material unavailable"
   assert current["name"]==item["name"] and current.get("unit","un")==item["unit"], "Catalog record changed"
batch=db.batch()
created=[]
for model in payload:
 ref=db.collection("shoppingLists").document(model["id"])
 snap=ref.get()
 if snap.exists:
  current=snap.to_dict()
  assert all(current.get(k)==v for k,v in model["data"].items()), "Existing template differs; no overwrite"
 else:
  batch.create(ref,{**model["data"],"createdAt":firestore.SERVER_TIMESTAMP,"updatedAt":firestore.SERVER_TIMESTAMP})
  created.append(model["id"])
if created: batch.commit()
for model in payload:
 saved=db.collection("shoppingLists").document(model["id"]).get().to_dict()
 assert saved and all(saved.get(k)==v for k,v in model["data"].items()), "Verification failed"
 print("TEMPLATE_VERIFIED",json.dumps({"id":model["id"],"name":saved["name"],"items":len(saved["items"]),"catalogLinked":sum(bool(i["matId"]) for i in saved["items"]),"manualReview":sum(not i["matId"] for i in saved["items"]),"created":model["id"] in created}))
print("DATA_ONLY_IMPORT_COMPLETE: No catalog records, purchase lists, project data or hosted code modified.")
